import { ExtensionHostKind, registerExtension, type IExtensionManifest } from '@codingame/monaco-vscode-api/extensions'

interface ManifestEntry {
  id: string
  folder: string
  manifest: IExtensionManifest & { main?: string; browser?: string }
  nls?: Record<string, string>
  files: string[]
}

/**
 * Registers every extension listed in /extensions/manifest.json (generated by
 * scripts/fetch-extensions.mjs) as a built-in extension. Must run BEFORE the workbench is
 * initialized so that themes are available on first paint.
 */
export async function registerBuiltinExtensions(): Promise<string[]> {
  let entries: ManifestEntry[] = []
  try {
    const res = await fetch('/extensions/manifest.json', { cache: 'no-cache' })
    if (res.ok) entries = ((await res.json()) as { extensions: ManifestEntry[] }).extensions
  } catch (e) {
    console.warn('Could not load extensions manifest', e)
  }

  const registered: string[] = []
  for (const entry of entries) {
    try {
      const manifest = { ...entry.manifest }
      // Node-only entry points cannot run in the browser; keep the declarative contributions.
      if (manifest.main != null && manifest.browser == null) {
        delete manifest.main
        manifest.activationEvents = undefined
      }
      const base = `/extensions/${entry.folder}`
      const { registerFileUrl } = registerExtension(manifest, ExtensionHostKind.LocalWebWorker, { path: '/' })
      for (const file of entry.files) {
        registerFileUrl('/' + file, new URL(encodeURI(`${base}/${file}`), window.location.origin).toString())
      }
      registered.push(entry.id)
    } catch (e) {
      console.warn(`Failed to register extension ${entry.id}`, e)
    }
  }
  return registered
}
